// The one status grammar: shape + word (+ age). Colour is never the only signal.
// kinds: ok (filled dot) · fail (square) · busy (spinning ring) · wait (hollow ring)
const RUN_KIND = { passed: 'ok', succeeded: 'ok', failed: 'fail', error: 'fail', running: 'busy', queued: 'wait', pending: 'wait' };

export const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

export function mark(kind, word, age) {
  return `<span class="mark ${kind}"><span class="glyph" aria-hidden="true"></span><span class="word">${esc(word)}</span>${
    age ? `<span class="age">${esc(age)}</span>` : ''}</span>`;
}

export function runMark(status) {
  const s = String(status ?? 'unknown').toLowerCase();
  return mark(RUN_KIND[s] ?? 'wait', s[0].toUpperCase() + s.slice(1));
}

export function ago(t, now = Date.now()) {
  const s = Math.max(0, Math.round((now - t) / 1000));
  if (s < 5) return 'just now';
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  return `${Math.floor(s / 3600)}h ago`;
}

// conn: { state: 'checking' | 'live' | 'down' | 'demo', lastOk, lastCheck }
export function renderBadge(conn, now = Date.now()) {
  switch (conn.state) {
    case 'live': return mark('ok', 'API live', `checked ${ago(conn.lastCheck, now)}`);
    case 'down': return mark('fail', 'API unreachable', conn.lastOk ? `last reached ${ago(conn.lastOk, now)}` : 'never reached');
    case 'demo': return mark('wait', 'Sample data', 'not connected');
    default:     return mark('busy', 'Checking API');
  }
}

