import { listRuns, retryRun, createRun, health } from './api/client.js';
import { renderBadge, runMark, mark, esc, ago } from './components/StatusBadge.js';

// ?demo shows fixture rows, clearly labelled, with actions off. Never mixed with live data.
const DEMO = new URLSearchParams(location.search).has('demo');
const SAMPLE = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'running', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];
const POLL_MS = 15000;
const MAX_ROWS = 100; // ponytail: render cap, paginate if the API ever returns more than this routinely

const $ = (s) => document.querySelector(s);
const state = {
  conn: { state: DEMO ? 'demo' : 'checking', lastOk: 0, lastCheck: 0 },
  runs: null,        // null = never loaded
  runsAt: 0,
  runsError: null,
  pending: new Set(),   // run ids with a retry in flight
  rowErrors: new Map(), // run id -> message
};

const httpError = (res) => new Error(`HTTP ${res.status}${res.statusText ? ` ${res.statusText}` : ''}`);
const reason = (e) => (e instanceof SyntaxError ? 'the API returned something other than JSON' : e.message || 'network error');

function fmtStarted(v) {
  const d = new Date(v);
  if (typeof v !== 'string' || !v.includes('T') || isNaN(d)) return { text: v ?? '', title: '' };
  return { text: d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), title: d.toLocaleString() };
}

// ---------- render ----------

function renderConn() {
  $('#conn').innerHTML = renderBadge(state.conn);
}

function skeleton() {
  return Array.from({ length: 4 }, () =>
    `<tr class="skel" aria-hidden="true">${'<td><span></span></td>'.repeat(6)}</tr>`).join('');
}

function messageRow(kind, word, text, action = '') {
  return `<tr class="msg"><td colspan="6"><div class="msg-body">${mark(kind, word)}<p>${text}</p>${action}</div></td></tr>`;
}

function row(r) {
  const busy = state.pending.has(r.id);
  const err = state.rowErrors.get(r.id);
  const failed = /^(failed|error)$/i.test(r.status);
  const st = fmtStarted(r.started);
  const off = DEMO ? ' disabled aria-describedby="notice-text"' : '';
  return `<tr class="${failed ? 'is-failed' : ''}">
    <th scope="row" class="id">${esc(r.id)}</th>
    <td class="svc" title="${esc(r.service)}">${esc(r.service)}</td>
    <td>${busy ? mark('busy', 'Retrying') : runMark(r.status)}</td>
    <td class="num"${st.title ? ` title="${esc(st.title)}"` : ''}>${esc(st.text)}</td>
    <td class="num">${esc(r.duration)}</td>
    <td class="act">
      ${err ? `<span class="act-err" id="err-${esc(r.id)}" title="${esc(err)}">${esc(err)}</span>` : ''}
      <button class="btn ${failed ? '' : 'quiet'}" data-run="${esc(r.id)}"${busy ? ' disabled' : ''}${off}
        aria-label="Retry ${esc(r.id)} (${esc(r.service)})"${err ? ` aria-describedby="err-${esc(r.id)}"` : ''}>${busy ? 'Retrying…' : 'Retry'}</button>
    </td>
  </tr>`;
}

function renderRuns() {
  const body = $('#runs');
  const focused = document.activeElement?.dataset?.run;
  const summary = $('#summary');
  const notice = $('#notice');

  if (state.runs === null) {
    body.innerHTML = state.runsError
      ? messageRow('fail', "Couldn't load runs", `pulse asked <code>/api/runs</code> and got ${esc(state.runsError)}.`,
          '<button class="btn" data-reload>Try again</button>')
      : skeleton();
    body.setAttribute('aria-busy', String(!state.runsError));
    summary.textContent = state.runsError ? '' : 'Loading…';
  } else if (state.runs.length === 0) {
    body.removeAttribute('aria-busy');
    body.innerHTML = messageRow('wait', 'No runs yet', 'Start one with New run. It will show up here within a few seconds.');
    summary.textContent = '';
  } else {
    body.removeAttribute('aria-busy');
    const shown = state.runs.slice(0, MAX_ROWS);
    body.innerHTML = shown.map(row).join('');
    const failed = state.runs.filter((r) => /^(failed|error)$/i.test(r.status)).length;
    const count = state.runs.length > MAX_ROWS ? `Latest ${MAX_ROWS} of ${state.runs.length} runs` : `${state.runs.length} ${state.runs.length === 1 ? 'run' : 'runs'}`;
    summary.innerHTML = `${count}, ${failed ? `<strong class="bad">${failed} failed</strong>` : 'none failed'}`;
  }

  // The notice bar: demo label, or "you are looking at old data".
  if (DEMO) {
    notice.innerHTML = `<div class="notice">${mark('wait', 'Sample data')}<p id="notice-text">These rows are fixtures, not your deploys. Retry and New run are off in this view.</p></div>`;
  } else if (state.runs && state.runsError) {
    notice.innerHTML = `<div class="notice warn">${mark('fail', 'Out of date')}<p>Couldn't refresh (${esc(state.runsError)}). Showing runs from ${ago(state.runsAt)}.</p><button class="btn" data-reload>Try again</button></div>`;
  } else {
    notice.innerHTML = '';
  }

  if (focused) body.querySelector(`[data-run="${CSS.escape(focused)}"]`)?.focus();
}

// ---------- data ----------

async function checkHealth() {
  const prev = state.conn.state;
  try {
    await health();
    state.conn = { state: 'live', lastOk: Date.now(), lastCheck: Date.now() };
  } catch {
    state.conn = { ...state.conn, state: 'down', lastCheck: Date.now() };
  }
  renderConn();
  if (prev !== state.conn.state) $('#announce').textContent = state.conn.state === 'live' ? 'API live' : 'API unreachable';
}

async function loadRuns() {
  try {
    const data = await listRuns();
    if (!Array.isArray(data)) throw new Error('an unexpected response shape');
    state.runs = data;
    state.runsAt = Date.now();
    state.runsError = null;
  } catch (e) {
    state.runsError = reason(e);
  }
  renderRuns();
  const svcs = [...new Set((state.runs ?? []).map((r) => r.service))];
  $('#svc-list').innerHTML = svcs.map((s) => `<option value="${esc(s)}">`).join('');
}

async function tick() {
  if (DEMO) return;
  await Promise.all([checkHealth(), loadRuns()]);
}

// ---------- actions ----------

$('#runs').addEventListener('click', async (e) => {
  const btn = e.target.closest('button');
  if (!btn) return;
  if (btn.hasAttribute('data-reload')) return loadRuns();
  const id = btn.dataset.run;
  if (!id || state.pending.has(id)) return;
  state.pending.add(id);
  state.rowErrors.delete(id);
  renderRuns();
  try {
    const res = await retryRun(id);
    if (!res.ok) throw httpError(res);
    $('#announce').textContent = `Retry started for ${id}`;
  } catch (err) {
    state.rowErrors.set(id, `Retry failed: ${reason(err)}`);
    $('#announce').textContent = `Retry failed for ${id}`;
  }
  state.pending.delete(id);
  await loadRuns();
});
$('#notice').addEventListener('click', (e) => e.target.closest('[data-reload]') && loadRuns());

const form = $('#new-run-form');
form.addEventListener('submit', async (e) => {
  e.preventDefault();
  const submit = form.querySelector('[type=submit]');
  if (submit.disabled) return;
  const service = form.service.value.trim();
  const errEl = $('#svc-err');
  errEl.textContent = '';
  submit.disabled = true;
  submit.textContent = 'Starting…';
  try {
    const res = await createRun({ service });
    if (!res.ok) throw httpError(res);
    form.hidePopover();
    form.reset();
    $('#announce').textContent = `Run started for ${service}`;
    await loadRuns();
  } catch (err) {
    errEl.textContent = `Couldn't start the run: ${reason(err)}.`;
  } finally {
    submit.disabled = false;
    submit.textContent = 'Start run';
  }
});
form.addEventListener('toggle', (e) => e.newState === 'open' && form.service.focus());

if (DEMO) {
  $('#new-run').disabled = true;
  $('#new-run').setAttribute('aria-describedby', 'notice-text');
  state.runs = SAMPLE;
}

renderConn();
renderRuns();
tick();
