// Verification-only static server. Not part of the app. PORT, MODE=down|ok|empty|many|slow
import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, extname } from 'node:path';
const root = new URL('..', import.meta.url).pathname.replace(/^\/(\w:)/, '$1');
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
const runs = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '2026-09-24T09:12:00Z', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing-reconciliation-worker', status: 'failed', started: '2026-09-24T08:58:00Z', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog', status: 'running', started: '2026-09-24T08:31:00Z', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify', status: 'queued', started: '2026-09-24T08:04:00Z', duration: '0m 51s' },
];
const many = Array.from({ length: 140 }, (_, i) => ({ ...runs[i % 4], id: `r-${2000 - i}` }));
const mode = process.env.MODE || 'down';
http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  if (url.pathname.startsWith('/api/')) {
    if (mode === 'down') { res.writeHead(502); return res.end(); }
    if (mode === 'slow') return; // hang forever: loading state
    const json = (o) => { res.writeHead(200, { 'content-type': 'application/json' }); res.end(JSON.stringify(o)); };
    if (url.pathname === '/api/health') return json({ ok: true });
    if (url.pathname === '/api/runs' && req.method === 'GET') return json(mode === 'empty' ? [] : mode === 'many' ? many : runs);
    res.writeHead(500); return res.end(); // retry / create fail: exercise inline errors
  }
  const p = join(root, url.pathname === '/' ? 'index.html' : url.pathname);
  try { const b = await readFile(p); res.writeHead(200, { 'content-type': types[extname(p)] || 'application/octet-stream' }); res.end(b); }
  catch { res.writeHead(404); res.end(); }
}).listen(+process.env.PORT || 5180);

