// Verification-only: headless Edge over CDP. Screenshots + overflow/target/keyboard checks.
import { spawn } from 'node:child_process';
import { writeFileSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const here = new URL('.', import.meta.url).pathname.replace(/^\/(\w:)/, '$1');
const shots = join(here, 'shots'); mkdirSync(shots, { recursive: true });
const MODES = { ok: 5181, down: 5182, empty: 5183, many: 5184, slow: 5185 };
const procs = Object.entries(MODES).map(([m, p]) => spawn(process.execPath, [join(here, 'serve.mjs'), p, m], { stdio: 'ignore' }));
const edge = spawn('C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
  ['--headless=new', '--remote-debugging-port=9333', `--user-data-dir=${join(tmpdir(), 'pulse-edge')}`, '--no-first-run', 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const out = [];
const log = (...a) => { console.log(...a); out.push(a.join(' ')); };

try {
  let tgt;
  for (let i = 0; i < 40 && !tgt; i++) { await sleep(250); try { tgt = (await (await fetch('http://127.0.0.1:9333/json')).json()).find((t) => t.type === 'page'); } catch {} }
  const ws = new WebSocket(tgt.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener('open', r));
  let id = 0; const wait = new Map(); const errors = [];
  ws.addEventListener('message', (e) => {
    const m = JSON.parse(e.data);
    if (m.id && wait.has(m.id)) { wait.get(m.id)(m.result); wait.delete(m.id); }
    if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.exception?.description ?? m.params.exceptionDetails.text);
    if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') errors.push(m.params.args.map((a) => a.value ?? a.description).join(' '));
