.act { text-align: end !important; }
.act-err {
  display: inline-block; max-width: 7.5rem; vertical-align: middle; margin-inline-end: var(--s2);
  overflow: hidden; text-overflow: ellipsis; color: var(--fail); font-size: 0.8125rem;
}

.msg td { height: auto; white-space: normal; padding: var(--s6) var(--s4); }
.msg-body { display: flex; flex-direction: column; align-items: center; gap: var(--s2); text-align: center; }
.msg-body p { margin: 0; color: var(--muted); max-width: 45ch; }

.skel span {
