:root {
  color-scheme: light dark;
  /* neutrals tinted toward hue 255; one accent (blue) for primary action + in-progress */
  --bg:      light-dark(oklch(0.985 0.003 255), oklch(0.17 0.008 255));
  --surface: light-dark(oklch(1 0 0),          oklch(0.21 0.009 255));
  --sunk:    light-dark(oklch(0.965 0.004 255), oklch(0.19 0.008 255));
  --line:    light-dark(oklch(0.90 0.006 255), oklch(0.30 0.010 255));
  --edge:    light-dark(oklch(0.62 0.010 255), oklch(0.56 0.012 255)); /* control borders, ≥3:1 */
  --ink:     light-dark(oklch(0.22 0.012 255), oklch(0.94 0.005 255));
  --muted:   light-dark(oklch(0.46 0.012 255), oklch(0.74 0.010 255));
  --accent:  light-dark(oklch(0.50 0.17 260),  oklch(0.72 0.14 255));
  --on-accent: light-dark(oklch(1 0 0),        oklch(0.17 0.02 255));
  --ok:      light-dark(oklch(0.52 0.13 150),  oklch(0.76 0.15 150));
  --fail:    light-dark(oklch(0.53 0.19 27),   oklch(0.72 0.16 25));
  --fail-bg: light-dark(oklch(0.97 0.015 27),  oklch(0.24 0.03 25));
  --ring:    var(--accent);

  --s1: 0.25rem; --s2: 0.5rem; --s3: 0.75rem; --s4: 1rem; --s5: 1.5rem; --s6: 2.5rem;
  --r1: 4px; --r2: 8px;
  --z-sticky: 10; --z-popover: 30;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);

  font: 400 0.875rem/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--ink);
  accent-color: var(--accent);
}
* { box-sizing: border-box; }
body { margin: 0; min-height: 100dvh; }
::selection { background: color-mix(in oklch, var(--accent) 30%, transparent); }
:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; border-radius: var(--r1); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
code { font: 0.9em ui-monospace, "Cascadia Mono", Menlo, monospace; }

/* ---------- top bar ---------- */
.bar {
  display: flex; align-items: center; gap: var(--s4); flex-wrap: wrap;
  padding: var(--s3) var(--s5);
  background: var(--surface); border-bottom: 1px solid var(--line);
}
.brand { font-size: 1rem; font-weight: 650; letter-spacing: -0.01em; margin: 0; }
.conn { margin-inline-end: auto; }
.new-run { position: relative; }

/* ---------- the status mark (signature) ---------- */
.mark { display: inline-flex; align-items: center; gap: var(--s2); white-space: nowrap; min-width: 0; }
.mark .word { font-weight: 550; }
.mark .age { color: var(--muted); font-variant-numeric: tabular-nums; }
.glyph { width: 0.625rem; height: 0.625rem; flex: none; border-radius: 50%; }
.ok   .glyph { background: var(--ok); }
.fail .glyph { background: var(--fail); border-radius: 2px; }
.wait .glyph { border: 2px solid var(--muted); }
.busy .glyph { border: 2px solid var(--accent); border-right-color: transparent; animation: spin 0.9s linear infinite; }
.ok .word { color: var(--ok); }
.fail .word { color: var(--fail); }
.busy .word { color: var(--accent); }
@keyframes spin { to { transform: rotate(1turn); } }
@media (prefers-reduced-motion: reduce) {
  .busy .glyph { animation: none; border-right-color: var(--accent); border-bottom-color: transparent; }
}

/* ---------- buttons ---------- */
.btn {
  font: inherit; font-weight: 550; color: var(--ink);
  min-height: 2rem; padding: 0 var(--s3);
  background: var(--surface); border: 1px solid var(--edge); border-radius: var(--r1);
  cursor: pointer; touch-action: manipulation;
  transition: background-color 150ms var(--ease), border-color 150ms var(--ease);
}
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); }
.btn.quiet { border-color: transparent; background: transparent; color: var(--muted); }
@media (hover: hover) {
  .btn:hover:not(:disabled) { background: var(--sunk); border-color: var(--edge); color: var(--ink); }
  .btn.primary:hover:not(:disabled) { background: color-mix(in oklch, var(--accent) 88%, var(--ink)); color: var(--on-accent); }
}
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled { cursor: not-allowed; opacity: 0.55; }
.btn[aria-disabled="true"] { cursor: progress; }
@media (pointer: coarse) { .btn { min-height: 2.75rem; } }

/* ---------- new run popover ---------- */
.pop {
  position: fixed; inset: auto; margin: 0;
  top: 3.5rem; right: var(--s5);
  width: min(20rem, calc(100vw - 2rem));
  padding: var(--s4); display: none; gap: var(--s2); flex-direction: column;
  background: var(--surface); color: var(--ink);
  border: 1px solid var(--line); border-radius: var(--r2);
  box-shadow: 0 8px 24px -8px oklch(0 0 0 / 0.25);
}
.pop:popover-open { display: flex; }
.pop label { font-weight: 550; }
.pop input {
  font: inherit; font-size: 1rem; color: var(--ink);
  padding: var(--s2) var(--s3); min-height: 2.5rem;
  background: var(--bg); border: 1px solid var(--edge); border-radius: var(--r1);
}
.field-err { margin: 0; color: var(--fail); min-height: 1.45em; }
.pop-actions { display: flex; justify-content: flex-end; gap: var(--s2); }

/* ---------- main ---------- */
main { padding: var(--s5); max-width: 80rem; margin-inline: auto; }
.head-row { display: flex; align-items: baseline; gap: var(--s4); flex-wrap: wrap; margin: var(--s2) 0 var(--s3); }
h2 { font-size: 1.125rem; font-weight: 650; margin: 0; }
.summary { margin: 0; color: var(--muted); font-variant-numeric: tabular-nums; }
.summary .bad { color: var(--fail); font-weight: 600; }

.notice {
  display: flex; align-items: center; gap: var(--s3); flex-wrap: wrap;
  padding: var(--s3) var(--s4); margin-bottom: var(--s4);
  background: var(--sunk); border: 1px solid var(--line); border-radius: var(--r2);
}
.notice.warn { background: var(--fail-bg); }
.notice p { margin: 0; flex: 1 1 16rem; }

/* ---------- table ---------- */
.table-wrap {
