  --z-sticky: 10; --z-popover: 30;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);

  font: 400 0.875rem/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--ink);
  accent-color: var(--accent);
}
* { box-sizing: border-box; }
body { margin: 0; min-height: 100dvh; }
::selection { background: color-mix(in oklch, var(--accent) 30%, transparent); }
:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; border-radius: var(--r1); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
code { font: 0.9em ui-monospace, "Cascadia Mono", Menlo, monospace; }

/* ---------- top bar ---------- */
.bar {
  display: flex; align-items: center; gap: var(--s4); flex-wrap: wrap;
  padding: var(--s3) var(--s5);
  background: var(--surface); border-bottom: 1px solid var(--line);
}
.brand { font-size: 1rem; font-weight: 650; letter-spacing: -0.01em; margin: 0; }
.conn { margin-inline-end: auto; }
.new-run { position: relative; }

/* ---------- the status mark (signature) ---------- */
.mark { display: inline-flex; align-items: center; gap: var(--s2); white-space: nowrap; min-width: 0; }
.mark .word { font-weight: 550; }
.mark .age { color: var(--muted); font-variant-numeric: tabular-nums; }
.glyph { width: 0.625rem; height: 0.625rem; flex: none; border-radius: 50%; }
.ok   .glyph { background: var(--ok); }
.fail .glyph { background: var(--fail); border-radius: 2px; }
.wait .glyph { border: 2px solid var(--muted); }
.busy .glyph { border: 2px solid var(--accent); border-right-color: transparent; animation: spin 0.9s linear infinite; }
.ok .word { color: var(--ok); }
.fail .word { color: var(--fail); }
.busy .word { color: var(--accent); }
@keyframes spin { to { transform: rotate(1turn); } }
@media (prefers-reduced-motion: reduce) {
  .busy .glyph { animation: none; border-right-color: var(--accent); border-bottom-color: transparent; }
}

/* ---------- buttons ---------- */
.btn {
  font: inherit; font-weight: 550; color: var(--ink);
  min-height: 2rem; padding: 0 var(--s3);
  background: var(--surface); border: 1px solid var(--edge); border-radius: var(--r1);
  cursor: pointer; touch-action: manipulation;
  transition: background-color 150ms var(--ease), border-color 150ms var(--ease);
}
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); }
.btn.quiet { border-color: transparent; background: transparent; color: var(--muted); }
@media (hover: hover) {
  .btn:hover:not(:disabled) { background: var(--sunk); border-color: var(--edge); color: var(--ink); }
  .btn.primary:hover:not(:disabled) { background: color-mix(in oklch, var(--accent) 88%, var(--ink)); color: var(--on-accent); }
}
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled { cursor: not-allowed; opacity: 0.55; }
.btn[aria-disabled="true"] { cursor: progress; }
@media (pointer: coarse) { .btn { min-height: 2.75rem; } }

/* ---------- new run popover ---------- */
.pop {
  position: fixed; inset: auto; margin: 0;
  top: 3.5rem; right: var(--s5);
  width: min(20rem, calc(100vw - 2rem));
  padding: var(--s4); display: none; gap: var(--s2); flex-direction: column;
  background: var(--surface); color: var(--ink);
  border: 1px solid var(--line); border-radius: var(--r2);
  box-shadow: 0 8px 24px -8px oklch(0 0 0 / 0.25);
}
.pop:popover-open { display: flex; }
.pop label { font-weight: 550; }
.pop input {
  font: inherit; font-size: 1rem; color: var(--ink);
  padding: var(--s2) var(--s3); min-height: 2.5rem;
  background: var(--bg); border: 1px solid var(--edge); border-radius: var(--r1);
}
.field-err { margin: 0; color: var(--fail); min-height: 1.45em; }
.pop-actions { display: flex; justify-content: flex-end; gap: var(--s2); }

/* ---------- main ---------- */
main { padding: var(--s5); max-width: 80rem; margin-inline: auto; }
.head-row { display: flex; align-items: baseline; gap: var(--s4); flex-wrap: wrap; margin: var(--s2) 0 var(--s3); }
h2 { font-size: 1.125rem; font-weight: 650; margin: 0; }
.summary { margin: 0; color: var(--muted); font-variant-numeric: tabular-nums; }
.summary .bad { color: var(--fail); font-weight: 600; }

.notice {
  display: flex; align-items: center; gap: var(--s3); flex-wrap: wrap;
  padding: var(--s3) var(--s4); margin-bottom: var(--s4);
  background: var(--sunk); border: 1px solid var(--line); border-radius: var(--r2);
}
.notice.warn { background: var(--fail-bg); }
.notice p { margin: 0; flex: 1 1 16rem; }

/* ---------- table ---------- */
.table-wrap {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r2);
  overflow: auto; max-height: calc(100dvh - 10rem);
  scroll-padding-top: 2.5rem; /* sticky thead never covers a focused row */
}
table { width: 100%; min-width: 54rem; border-collapse: collapse; table-layout: fixed; }
col.c-id { width: 7rem; } col.c-status { width: 9rem; } col.c-time { width: 7.5rem; }
col.c-dur { width: 6.5rem; } col.c-act { width: 16rem; }
thead th {
  position: sticky; top: 0; z-index: var(--z-sticky);
  background: var(--sunk); color: var(--muted);
  font-weight: 550; text-align: start;
  height: 2.5rem; padding: 0 var(--s4); border-bottom: 1px solid var(--line);
}
tbody th, tbody td {
  height: 2.75rem; padding: 0 var(--s4);
  text-align: start; font-weight: 400;
  border-bottom: 1px solid var(--line);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
tbody tr:last-child > * { border-bottom: 0; }
.num { text-align: end !important; font-variant-numeric: tabular-nums; }
.id { font: 0.8125rem ui-monospace, "Cascadia Mono", Menlo, monospace; color: var(--muted); }
/* first column stays put when the table scrolls sideways on narrow screens */
thead th:first-child { left: 0; z-index: calc(var(--z-sticky) + 1); }
tbody th.id { position: sticky; left: 0; background: var(--surface); }
tr.is-failed th.id { background: var(--fail-bg); }
.svc { font-weight: 550; }
tr.is-failed { background: var(--fail-bg); }
@media (hover: hover) { tbody tr:not(.msg, .skel):hover, tbody tr:not(.is-failed):hover th.id { background: var(--sunk); } tbody tr.is-failed:hover { background: var(--fail-bg); } }
.act > div { display: flex; align-items: center; justify-content: flex-end; gap: var(--s2); }
.act .btn { flex: none; min-width: 5.5rem; }
.act-err { min-width: 0; overflow: hidden; text-overflow: ellipsis; color: var(--fail); font-size: 0.8125rem; }

.msg td { height: auto; white-space: normal; padding: var(--s6) var(--s4); }
.msg-body { display: flex; flex-direction: column; align-items: center; gap: var(--s2); text-align: center; }
.msg-body p { margin: 0; color: var(--muted); max-width: 45ch; }

.skel span {
  display: block; height: 0.75rem; width: 70%; border-radius: var(--r1);
  background: var(--line);
  animation: fade 1.2s ease-in-out infinite alternate;
}
.skel td:last-child span { width: 5.5rem; margin-inline-start: auto; }
@keyframes fade { from { opacity: 0.5; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .skel span { animation: none; } }

@media (max-width: 40rem) {
  .bar, main { padding-inline: var(--s4); }
  .pop { right: var(--s4); }
}

tool_input.command:
node --input-type=module <<'EOF'
const f=(n)=>n<=0.0031308?12.92*n:1.055*Math.pow(n,1/2.4)-0.055;
const o=(L,C,H)=>{const h=H*Math.PI/180,a=C*Math.cos(h),b=C*Math.sin(h);
  const l=(L+0.3963377774*a+0.2158037573*b)**3, m=(L-0.1055613458*a-0.0638541728*b)**3, s=(L-0.0894841775*a-1.2914855480*b)**3;
  return [4.0767416621*l-3.3077115913*m+0.2309699292*s,-1.2684380046*l+2.6097574011*m-0.3413193965*s,-0.0041960863*l-0.7034186147*m+1.7076147010*s].map(v=>Math.round(Math.min(1,Math.max(0,f(v)))*255));};
const lum=([r,g,b])=>{const c=[r,g,b].map(v=>{v/=255;return v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4;});return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2];};
const R=(A,B)=>{const [x,y]=[lum(A),lum(B)].sort((p,q)=>q-p);return +((x+0.05)/(y+0.05)).toFixed(2);};
const T={light:{bg:o(.985,.003,255),surface:o(1,0,0),sunk:o(.965,.004,255),edge:o(.62,.01,255),ink:o(.22,.012,255),muted:o(.46,.012,255),accent:o(.5,.17,260),on:o(1,0,0),ok:o(.52,.13,150),fail:o(.53,.19,27),failbg:o(.97,.015,27)},
dark:{bg:o(.17,.008,255),surface:o(.21,.009,255),sunk:o(.19,.008,255),edge:o(.56,.012,255),ink:o(.94,.005,255),muted:o(.74,.01,255),accent:o(.72,.14,255),on:o(.17,.02,255),ok:o(.76,.15,150),fail:o(.72,.16,25),failbg:o(.24,.03,25)}};
for (const [n,t] of Object.entries(T)) {
  const p=[['ink/surface',t.ink,t.surface],['ink/failbg',t.ink,t.failbg],['muted/surface',t.muted,t.surface],['muted/sunk',t.muted,t.sunk],['muted/failbg',t.muted,t.failbg],
  ['ok/surface',t.ok,t.surface],['ok/sunk(hover)',t.ok,t.sunk],['fail/surface',t.fail,t.surface],['fail/failbg',t.fail,t.failbg],['accent/surface',t.accent,t.surface],['accent/failbg',t.accent,t.failbg],
  ['on/accent',t.on,t.accent],['edge/surface(3)',t.edge,t.surface],['edge/failbg(3)',t.edge,t.failbg],['ring/bg(3)',t.accent,t.bg],['muted/bg',t.muted,t.bg],['fail/bg',t.fail,t.bg]];
  console.log(n, p.map(([k,a,b])=>`${k} ${R(a,b)}`).join(' | '));
}
EOF
